"""Kaggle entry for the Model A parameter count.

Unpacks the repo sources and runs scripts/model_a_params.py.
Does not train and does not download MovingMNIST.
GPU stays off: this script never requests an accelerator, and the kernel
metadata sets enable_gpu and enable_internet to false.
"""

from __future__ import annotations

import base64
import json
import os
import runpy
import sys
import tempfile
from pathlib import Path

PAYLOAD = json.loads(r"""
{
  "src/dl4stg/__init__.py": "IiIiREw0U1RHIEFzc2lnbm1lbnQgMiBwYWNrYWdlLiIiIg0K",
  "src/dl4stg/convlstm.py": "",
  "src/dl4stg/model_a.py": "",
  "scripts/model_a_params.py": ""
}
""")


def main() -> None:
    dest = Path(tempfile.mkdtemp(prefix="dl4stg_model_a_"))
    for rel, b64 in PAYLOAD.items():
        path = dest / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(b64))
    working = Path("/kaggle/working")
    if working.is_dir():
        os.chdir(working)
    script = dest / "scripts" / "model_a_params.py"
    sys.path.insert(0, str(dest / "src"))
    runpy.run_path(str(script), run_name="__main__")


if __name__ == "__main__":
    main()
